type AnalyticsParams = Record<string, string | number | boolean | undefined>;

const GA_TRACKING_ID = "G-B09Y6PL7JC";
const CONSENT_KEY = "cookie-consent";
type ConsentValue = "granted" | "denied";

// Module-level singletons — survive Layout remounts across Gatsby navigations
let analyticsLoadPromise: Promise<void> | null = null;
let analyticsStarted = false;
let gtagInitialized = false; // guards initGtagStub so it only runs once

declare global {
  interface Window {
    dataLayer?: unknown[][];
    gtag?: (...args: unknown[]) => void;
  }
}

// ── Consent storage ───────────────────────────────────────────────────

export function getStoredConsent(): ConsentValue | null {
  if (typeof window === "undefined") return null;
  const val = localStorage.getItem(CONSENT_KEY);
  return val === "granted" || val === "denied" ? val : null;
}

function storeConsent(value: ConsentValue): void {
  if (typeof window !== "undefined") {
    localStorage.setItem(CONSENT_KEY, value);
  }
}

// ── gtag stub + Consent Mode v2 default ───────────────────────────────
// Called ONCE before loading the gtag.js script.
// The gtagInitialized guard prevents this from running again on Layout remounts.

function initGtagStub(initialConsent: ConsentValue): void {
  if (gtagInitialized) return;
  gtagInitialized = true;

  window.dataLayer = window.dataLayer || [];
  if (typeof window.gtag !== "function") {
    window.gtag = (...args: unknown[]) => {
      window.dataLayer!.push(args);
    };
  }

  // Consent Mode v2 — must come before js/config
  window.gtag("consent", "default", {
    analytics_storage: initialConsent,
    ad_storage: "denied",
    ad_user_data: "denied",
    ad_personalization: "denied",
    wait_for_update: 500,
  });
  window.gtag("js", new Date());
  window.gtag("config", GA_TRACKING_ID, { send_page_view: false });
}

// ── Script loader ─────────────────────────────────────────────────────

export function isAnalyticsStarted(): boolean {
  return analyticsStarted;
}

export function loadAnalytics(): Promise<void> {
  if (typeof window === "undefined") return Promise.resolve();
  if (analyticsLoadPromise) return analyticsLoadPromise;

  analyticsStarted = true;

  analyticsLoadPromise = new Promise<void>((resolve, reject) => {
    const existing = document.querySelector<HTMLScriptElement>(
      `script[src*="${GA_TRACKING_ID}"]`
    );
    if (existing) { resolve(); return; }

    const script = document.createElement("script");
    script.async = true;
    script.src = `https://www.googletagmanager.com/gtag/js?id=${GA_TRACKING_ID}`;
    script.onload = () => resolve();
    script.onerror = () => {
      // Reset so it can be retried (e.g. user disables ad blocker)
      analyticsLoadPromise = null;
      analyticsStarted = false;
      gtagInitialized = false;
      const msg = "GA4 script blocked or failed to load (ad blocker?)";
      if (process.env.NODE_ENV === "development") console.warn("[Analytics]", msg);
      reject(new Error(msg));
    };
    document.head.appendChild(script);
  });

  return analyticsLoadPromise;
}

// ── Consent actions ───────────────────────────────────────────────────

/** Called when the user clicks Accept in the cookie banner. */
export function grantConsent(): Promise<void> {
  storeConsent("granted");
  if (typeof window === "undefined") return Promise.resolve();

  if (!gtagInitialized) {
    // First time: stub + consent default as granted, then load script
    initGtagStub("granted");
  } else {
    // Stub/script already running: upgrade consent in place
    window.gtag?.("consent", "update", { analytics_storage: "granted" });
  }
  return loadAnalytics();
}

/** Called when the user clicks Decline in the cookie banner. */
export function denyConsent(): void {
  storeConsent("denied");
  // Script was never loaded — nothing else to do.
}

/** Called on mount for returning users who already granted consent. */
export function initForGrantedConsent(): Promise<void> {
  if (typeof window === "undefined") return Promise.resolve();
  initGtagStub("granted"); // no-op after first call thanks to gtagInitialized
  return loadAnalytics();
}

// ── Tracking ──────────────────────────────────────────────────────────

export function trackPageView(pathname: string): void {
  if (typeof window === "undefined" || typeof window.gtag !== "function") return;
  window.gtag("event", "page_view", {
    page_path: pathname,
    page_location: window.location.href,
    page_title: document.title,
  });
}

export function trackEvent(eventName: string, params: AnalyticsParams = {}): void {
  if (typeof window === "undefined") return;
  window.gtag?.("event", eventName, params);
}
