import * as React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import {
  getStoredConsent,
  grantConsent,
  denyConsent,
  trackPageView,
} from "../utils/analytics";

interface CookieStrings {
  message: string;
  accept: string;
  decline: string;
}

export default function CookieConsent() {
  const { t } = useTranslation();
  const [visible, setVisible] = React.useState(false);

  React.useEffect(() => {
    if (typeof window === "undefined") return;
    // Only show if the user has never made a choice
    if (getStoredConsent() === null) {
      const id = window.setTimeout(() => setVisible(true), 600);
      return () => window.clearTimeout(id);
    }
  }, []);

  const handleAccept = () => {
    setVisible(false);
    void grantConsent().then(() => {
      const path =
        window.location.pathname +
        window.location.search +
        window.location.hash;
      trackPageView(path);
    });
  };

  const handleDecline = () => {
    setVisible(false);
    denyConsent();
  };

  if (!visible) return null;

  const c = t("cookies", { returnObjects: true }) as CookieStrings;

  return (
    <div
      className="cookie-banner"
      role="region"
      aria-label={c.accept}
      aria-live="polite"
    >
      <p className="cookie-msg">{c.message}</p>
      <div className="cookie-actions">
        <button
          type="button"
          className="btn btn-dark cookie-accept"
          onClick={handleAccept}
        >
          {c.accept}
        </button>
        <button
          type="button"
          className="cookie-decline"
          onClick={handleDecline}
        >
          {c.decline}
        </button>
      </div>
    </div>
  );
}
